    /**
     * Method to retrieve the Experiment via ExperimentFetchOneSummary
     * @param 	summary ExperimentFetchOneSummary 
     * @return 	ExperimentFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Experiment getExperiment( ExperimentFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ExperimentFetchOneSummary arg cannot be null" );
    	
    	Experiment entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Experiment
        	// --------------------------------------
        	CompletableFuture<Experiment> futureEntity = queryGateway.query(new FindExperimentQuery( new LoadExperimentFilter( summary.getExperimentId() ) ), ResponseTypes.instanceOf(Experiment.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Experiment with id " + summary.getExperimentId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


